function nodenoSeoEscape($value):string { return htmlspecialchars((string)($value??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function nodenoSeoLocal($value,string $locale):string { return nodenoLocaleLocal($value,$locale); }
function nodenoSeoText(string $value,int $max=170):string { return implode('',array_slice(preg_split('//u',trim(preg_replace('/\s+/u',' ',$value)),-1,PREG_SPLIT_NO_EMPTY),0,$max)); }
function nodenoSeoName(array $product,string $locale):string { return nodenoSeoLocal($product['modelName']??[], $locale)?:nodenoSeoLocal($product['name']??[], $locale); }
function nodenoSeoVisible(array $product):bool { return ($product['published']??true)!==false&&($product['hidden']??false)!==true; }
