function nodenoSeoWholesaleCopy(string $locale):array { return nodenoLocaleCopy(json_decode('{"tr": ["Yurt dışına toptan mobilya", "Mağazanız, dağıtım ağınız veya projeniz için ürünleri adet olarak seçin ya da ihtiyacınıza göre bir takım oluşturun. Ürün, takım sayısı ve teslimat ülkesine göre teklif isteyin.", "Adet ve takım bazında alım", "Bağımsız ürünleri adet olarak ekleyin. Takımınızı oluştururken dolap, komodin ve şifonyer gibi parçaları seçip her birinin adedini belirleyin.", "Miktarınıza göre teklif", "Toptan fiyatlar seçtiğiniz ürünler, takım içeriği ve miktara göre hazırlanır. Perakende fiyatlar toptan teklif yerine geçmez.", "Sevkiyatın birlikte planlanması", "Teslimat noktası, taşıma, ambalaj ve ülkeye bağlı vergi koşulları teklif aşamasında netleştirilir. Talep göndermek sipariş veya ödeme oluşturmaz.", "Toplu alım için teklif isteyin"], "en": ["Wholesale furniture for international buyers", "Choose individual products by quantity or build a furniture set for your store, distribution network or project. Request a quote for your products, number of sets and destination.", "Order by quantity or sets", "Add individual products by quantity. When building a set, choose pieces such as wardrobes, nightstands and dressers and specify the quantity of each.", "A quote for your quantities", "Wholesale pricing depends on your products, set composition and quantities. Retail prices do not represent a wholesale quotation.", "Plan your shipment with us", "Destination, transport, packaging and applicable tax terms are confirmed during quotation. Sending an inquiry does not place an order or take payment.", "Request a wholesale quote"], "ru": ["Мебель оптом для международных покупателей", "Выбирайте отдельные товары поштучно или соберите комплект для магазина, дистрибьюторской сети или проекта. Укажите товары, число комплектов и страну доставки для предложения.", "Заказ поштучно и комплектами", "Добавляйте отдельные товары по количеству. Собирая комплект, выбирайте шкафы, тумбы и комоды и указывайте количество каждого предмета.", "Предложение под ваш объём", "Оптовые цены зависят от выбранных товаров, состава и количества комплектов. Розничные цены не являются оптовым предложением.", "Планирование отгрузки", "Пункт назначения, перевозка, упаковка и применимые налоги уточняются при подготовке предложения. Отправка запроса не создаёт заказ или оплату.", "Запросить оптовое предложение"], "ar": ["أثاث بالجملة للمشترين الدوليين", "اختر المنتجات بالعدد أو كوّن طقم أثاث لمتجرك أو شبكة التوزيع أو مشروعك. اطلب عرضاً حسب المنتجات وعدد الأطقم وبلد التسليم.", "الطلب بالعدد أو بالأطقم", "أضف المنتجات المنفردة بالعدد. عند تكوين طقم، اختر الخزائن والطاولات الجانبية وخزائن الأدراج وحدد كمية كل قطعة.", "عرض يناسب كمياتك", "تعتمد أسعار الجملة على المنتجات ومحتويات الأطقم والكميات. أسعار التجزئة لا تمثل عرض أسعار بالجملة.", "تخطيط الشحنة معاً", "تُحدَّد الوجهة والنقل والتغليف والضرائب المطبقة أثناء إعداد العرض. إرسال الطلب لا ينشئ طلب شراء أو عملية دفع.", "اطلب عرض سعر بالجملة"]}',true,32,JSON_THROW_ON_ERROR),$locale); }
function nodenoSeoFurnitureSetCopy(string $locale):array { return nodenoLocaleCopy(json_decode('{"tr": ["Takımını oluştur", "Yatak odası, genç odası ve yaşam odası koleksiyonlarından ihtiyacınız olan parçaları ve adetlerini seçin. Seçmediğiniz karyola, baza veya diğer parçalar eklenmez."], "en": ["Build your furniture set", "Choose the pieces and quantities you need from bedroom, teen bedroom and living room collections. Beds, bases and other unselected pieces are not added."], "ru": ["Соберите свой комплект", "Выбирайте нужные предметы и количество из коллекций для спальни, подростковой и гостиной. Неотмеченные кровати, основания и другие предметы не добавляются."], "ar": ["كوّن طقم الأثاث الخاص بك", "اختر القطع والكميات التي تحتاجها من مجموعات غرف النوم والشباب والمعيشة. لا تُضاف الأسرّة والقواعد والقطع الأخرى التي لم تخترها."]}',true,32,JSON_THROW_ON_ERROR),$locale); }
function nodenoSeoUrl(string $kind='home',string $locale='tr',array $values=[]):string {
 $query=['lang'=>in_array($locale,NODENO_SEO_LOCALES,true)?$locale:'tr'];if(!in_array($kind,['home','product'],true))$query['page']=$kind;
 foreach(['category','product','set'] as $key)if(isset($values[$key])&&(string)$values[$key]!=='')$query[$key]=(string)$values[$key];
 if($kind==='catalog'&&isset($values['pg'])&&(int)$values['pg']>1)$query['pg']=(string)$values['pg'];
 return NODENO_SEO_ORIGIN.'/?'.http_build_query($query,'','&',PHP_QUERY_RFC3986);
}
function nodenoSeoLink(string $kind='home',string $locale='tr',array $values=[]):string { return substr(nodenoSeoUrl($kind,$locale,$values),strlen(NODENO_SEO_ORIGIN)); }
function nodenoSeoFamily(array $categories,string $id):array {
 $ids=[$id=>true];$changed=true;while($changed){$changed=false;foreach($categories as $category)if(isset($ids[$category['parentId']??''])&&!isset($ids[$category['id']])){$ids[$category['id']]=true;$changed=true;}}return $ids;
}
function nodenoSeoProducts(array $catalog,string $category=''):array {
 $family=$category!==''?nodenoSeoFamily($catalog['categories']??[],$category):null;
 return array_values(array_filter($catalog['products']??[],static function(array $p)use($family):bool { if(!nodenoSeoVisible($p))return false;if($family===null)return true;foreach($p['categoryIds']??[] as $id)if(isset($family[$id]))return true;return false; }));
}
function nodenoSeoDistinct(array $products):array { $result=[];$seen=[];foreach($products as $p){$key=$p['modelId']??$p['id'];if(!isset($seen[$key])){$seen[$key]=true;$result[]=$p;}}return $result; }
function nodenoSeoImages(array $product,array $catalog):array {
 $result=[];$type=$product['productType']??'';$version=str_starts_with($type,'door')?($catalog['meta']['doorCatalogVersion']??$catalog['meta']['mediaVersion']??''):(str_starts_with($type,'cabinet')?($catalog['meta']['frontCatalogVersion']??$catalog['meta']['mediaVersion']??''):($catalog['meta']['mediaVersion']??''));
 foreach($product['images']??[]as $src){
  if(!is_string($src))continue;
  if(preg_match('~^/media/'.preg_quote((string)$product['id'],'~').'/\d+$~D',$src))$result[]=NODENO_SEO_ORIGIN.$src.(preg_match('/^[a-f0-9]{64}$/D',$version)?'?v='.$version:'');
  elseif($type==='supplier-item'&&preg_match('~^/assets/suppliers/[a-f0-9]{64}\.(jpg|png|webp)$~D',$src))$result[]=NODENO_SEO_ORIGIN.$src;
 }
 return $result;
}
function nodenoSeoImage(array $product,array $catalog):string { $images=nodenoSeoImages($product,$catalog);$index=$product['coverIndex']??0;return $images[is_int($index)&&$index>=0&&$index<count($images)?$index:0]??''; }
function nodenoSeoPhoto(array $product,array $catalog,string $locale,bool $lazy=true):string {
 $src=str_replace(NODENO_SEO_ORIGIN,'',nodenoSeoImage($product,$catalog));return $src!==''?'<img class="product-image" src="'.nodenoSeoEscape($src).'" alt="'.nodenoSeoEscape(nodenoSeoName($product,$locale)).'" width="640" height="640" '.($lazy?'loading="lazy"':'fetchpriority="high"').' decoding="async" draggable="false">':'';
}
function nodenoSeoMinor(array $product):?int { $minor=$product['salePriceMinor']??null;return ($product['currency']??'')==='TRY'&&is_int($minor)&&$minor>0&&$minor<=intdiv(9007199254740991,9900)?$minor:null; }
function nodenoSeoAmount(int $minor):string { return intdiv($minor,100).'.'.str_pad((string)($minor%100),2,'0',STR_PAD_LEFT); }
function nodenoSeoPrice(array $product,string $locale):string {
 $minor=nodenoSeoMinor($product);if($minor===null)return nodenoSeoEscape(nodenoSeoCopy($locale)['price']);
 if(class_exists('NumberFormatter')){$format=new NumberFormatter($locale,NumberFormatter::CURRENCY);$value=$format->formatCurrency($minor/100,'TRY');if(is_string($value))return nodenoSeoEscape($value);}
 return nodenoSeoEscape(number_format($minor/100,2,$locale==='en'?'.':',',$locale==='en'?',':'.').' TRY');
}
function nodenoSeoCard(array $product,array $catalog,string $locale):string {
 $href=nodenoSeoEscape(nodenoSeoLink('product',$locale,['product'=>$product['id']]));return '<article class="product-card"><a class="product-stage" href="'.$href.'">'.nodenoSeoPhoto($product,$catalog,$locale).'</a><div class="product-info"><h3><a href="'.$href.'">'.nodenoSeoEscape(nodenoSeoName($product,$locale)).'</a></h3><p class="card-color">'.nodenoSeoEscape(nodenoSeoLocal($product['variantColor']??[],$locale)).'</p><p class="pricing-note">'.nodenoSeoPrice($product,$locale).'</p></div></article>';
}
function nodenoSeoBreadcrumb(array $catalog,?array $product,string $locale,string $category=''):array {
 $rows=[['name'=>nodenoSeoCopy($locale)['home'],'url'=>nodenoSeoUrl('home',$locale)]];$ids=$product['categoryIds']??[];$id=$category!==''?$category:($ids?end($ids):'');$byId=array_column($catalog['categories']??[],null,'id');$trail=[];$seen=[];
 while(isset($byId[$id])&&!isset($seen[$id])){$entry=$byId[$id];$seen[$id]=true;array_unshift($trail,['name'=>nodenoSeoLocal($entry['name'],$locale),'url'=>nodenoSeoUrl('catalog',$locale,['category'=>$entry['id']])]);$id=$entry['parentId']??'';}
 foreach($trail as $entry)$rows[]=$entry;
 if($product!==null)$rows[]=['name'=>nodenoSeoName($product,$locale),'url'=>nodenoSeoUrl('product',$locale,['product'=>$product['id']])];return $rows;
}
function nodenoSeoCrumbHtml(array $rows):string { return '<nav class="breadcrumb" aria-label="Breadcrumb">'.implode(' <span class="breadcrumb-separator" aria-hidden="true"></span> ',array_map(static fn(array $row):string=>'<a href="'.nodenoSeoEscape(str_replace(NODENO_SEO_ORIGIN,'',$row['url'])).'">'.nodenoSeoEscape($row['name']).'</a>',$rows)).'</nav>'; }
function nodenoSeoProductData(array $product,array $catalog,string $locale):array {
 $url=nodenoSeoUrl('product',$locale,['product'=>$product['id']]);$data=['@type'=>'Product','@id'=>$url.'#product','name'=>nodenoSeoVariantName($product,$locale),'sku'=>(string)$product['code'],'url'=>$url,'image'=>nodenoSeoImages($product,$catalog),'brand'=>['@type'=>'Brand','name'=>$product['productBrand']??'NODENO']];
 $data['description']=nodenoSeoDescription($product,$locale,$catalog);foreach(nodenoSeoAttributes($product,$locale)as $attribute=>$value)$data[$attribute]=$value;
 $minor=nodenoSeoMinor($product);$unitOnlyMinimum=($product['productType']??'')==='supplier-item'&&($product['quantityPolicy']['minimum']??1)>1;if($minor!==null&&!$unitOnlyMinimum&&empty($product['variationSelectionRequired'])&&($product['saleUnit']??'')!=='quote'&&!in_array($product['productType']??'',['door','door-profile','cabinet-front','cabinet-profile'],true))$data['offers']=['@type'=>'Offer','url'=>$url,'price'=>nodenoSeoAmount($minor),'priceCurrency'=>'TRY'];
 if(($product['stockKnown']??false)===true&&is_int($product['stockQuantity']??null)&&$product['stockQuantity']>=0&&isset($data['offers']))$data['offers']['availability']=$product['stockQuantity']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock';
 $specs=[];foreach($product['specs']??[] as $spec){$name=nodenoSeoLocal($spec['label']??[],$locale);$value=nodenoSeoLocal($spec['value']??[],$locale);if($name!==''&&$value!=='')$specs[]=['@type'=>'PropertyValue','name'=>$name,'value'=>$value];}if($specs)$data['additionalProperty']=$specs;return $data;
}
function nodenoSeoVariantName(array $product,string $locale):string {
 $name=nodenoSeoName($product,$locale);$variant=empty($product['variationSelectionRequired'])?nodenoSeoLocal($product['variantLabel']??[],$locale):'';
 $parts=[];foreach(explode(' / ',$variant)as $part){$value=trim(str_contains($part,':')?substr($part,strpos($part,':')+1):$part);if($value!==''&&!preg_match('/'.preg_quote($value,'/').'/iu',$name))$parts[]=$part;}
 return $parts?$name.' - '.implode(' / ',$parts):$name;
}
function nodenoSeoSearchName(array $product,array $catalog,string $locale,bool $withVariant=true):string {
 $name=nodenoSeoName($product,$locale);$title=$withVariant?nodenoSeoVariantName($product,$locale):$name;
 if(preg_match('/^[A-Za-z]{1,6}[-. ]?\d+$/D',$name)){$ids=$product['categoryIds']??[];$id=$ids?end($ids):'';foreach($catalog['categories']??[]as $category)if($category['id']===$id){$label=nodenoSeoLocal($category['name'],$locale);if($label!=='')$title.=' - '.$label;break;}}
 return $title;
}
function nodenoSeoDescription(array $product,string $locale,array $catalog=[]):string {
 $facts=[nodenoSeoSearchName($product,$catalog,$locale,false)];$variant=empty($product['variationSelectionRequired'])?nodenoSeoLocal($product['variantLabel']??(empty($product['colorReviewPending'])?($product['variantColor']??[]):[]),$locale):'';
 if($variant!=='')$facts[]=$variant;
 foreach(array_slice($product['specs']??[],0,2)as $spec){$label=nodenoSeoLocal($spec['label']??[],$locale);$value=nodenoSeoLocal($spec['value']??[],$locale);if($value!=='')$facts[]=($label!==''?$label.': ':'').$value;}
 $text=trim(strip_tags(nodenoSeoLocal($product['description']??[],$locale)));if($text!==''&&$text!==nodenoSeoName($product,$locale))$facts[]=$text;
 return nodenoSeoText(implode('. ',array_unique(array_filter($facts))));
}
function nodenoSeoAttributes(array $product,string $locale):array {
 $attributes=[];$color=empty($product['colorReviewPending'])?nodenoSeoLocal($product['variantColor']??[],$locale):'';if($color!=='')$attributes['color']=$color;$sizes=[];
 if(($product['productType']??'')==='supplier-item')foreach($product['specs']??[]as $spec){
  $label=nodenoSeoLocal($spec['label']??[],'tr');$value=nodenoSeoLocal($spec['value']??[],$locale);if($value==='')continue;
  if(preg_match('/^Ağaç cinsi$/iu',$label))$attributes['material']=$value;
  if(preg_match('/^(Çap|Genişlik|Kalınlık|Boy)$/iu',$label))$sizes[]=nodenoSeoLocal($spec['label'],$locale).': '.$value;
 }
 if($sizes)$attributes['size']=implode(' / ',$sizes);return $attributes;
}
function nodenoSeoVariantAxes(array $variants,string $locale):array {
 $values=['color'=>[],'material'=>[],'size'=>[]];foreach($variants as $variant)foreach(nodenoSeoAttributes($variant,$locale)as $key=>$value)$values[$key][$value]=true;
 return array_map(static fn(string $key):string=>'https://schema.org/'.$key,array_keys(array_filter($values,static fn(array $v):bool=>count($v)>1)));
}
function nodenoSeoCategoryDescription(array $catalog,string $category,string $locale,string $title,int $count):string {
 $names=[];foreach($catalog['categories']??[]as $c)if(($category!==''?($c['parentId']??'')===$category:empty($c['parentId']))&&nodenoSeoProducts($catalog,$c['id']))$names[]=nodenoSeoLocal($c['name'],$locale);
 $intro=nodenoLocaleCopy(['tr'=>'NODENO '.$title.' koleksiyonunda '.$count.' model.','en'=>'Explore '.$count.' models in the NODENO '.$title.' collection.','ru'=>'В коллекции NODENO «'.$title.'» представлено моделей: '.$count.'.','ar'=>'اكتشف '.$count.' طرازًا في مجموعة '.$title.' من NODENO.'],$locale);
 return nodenoSeoText($intro.($names?' '.implode(', ',array_slice($names,0,4)).'.':''));
}
function nodenoSeoPagination(string $kind,string $locale,array $values,int $page,int $pages):string {
 if($pages<2)return '';$label=nodenoLocaleCopy(['tr'=>'Sayfalar','en'=>'Pages','ru'=>'Страницы','ar'=>'الصفحات'],$locale);$parts=[];
 foreach(array_unique(array_merge([1,$pages],range(max(1,$page-2),min($pages,$page+2))))as $n)$parts[$n]='<a href="'.nodenoSeoEscape(nodenoSeoLink($kind,$locale,array_replace($values,['pg'=>$n]))).'"'.($n===$page?' aria-current="page"':'').'>'.$n.'</a>';
 ksort($parts);return '<nav class="pagination" aria-label="'.$label.'">'.implode(' ',$parts).'</nav>';
}
function nodenoSeoProductBody(array $product,array $catalog,string $locale,array $variants):string {
 $copy=nodenoSeoCopy($locale);$rows=nodenoSeoBreadcrumb($catalog,$product,$locale);$colors='';foreach($variants as $p)if(empty($p['variationSelectionRequired']))$colors.='<a class="color-option" href="'.nodenoSeoEscape(nodenoSeoLink('product',$locale,['product'=>$p['id']])).'">'.nodenoSeoPhoto($p,$catalog,$locale).'<span>'.nodenoSeoEscape(nodenoSeoLocal($p['variantLabel']??$p['variantColor']??[],$locale)).'</span></a>';
