function nodenoSeoDocument(string $html,array $page):string {
 $result=preg_replace('~<title\b[^>]*>[\s\S]*?</title>~iu','',$html);$result=preg_replace('~<meta\s+(?:property|name)=["\x27](?:description|robots|og:[^"\x27]*|twitter:[^"\x27]*)["\x27][^>]*>~iu','',$result);$result=preg_replace('~<link\s+[^>]*rel=["\x27](?:canonical|alternate)["\x27][^>]*>~iu','',$result);$result=preg_replace('~<script\b[^>]*data-nodeno-seo[^>]*>[\s\S]*?</script>~iu','',$result);
 $tags=['description'=>$page['description'],'robots'=>$page['indexable']?'index,follow,max-image-preview:large':'noindex,follow','og:title'=>$page['title'],'og:description'=>$page['description'],'og:type'=>$page['kind']==='product'?'product':'website','og:site_name'=>'NODENO','twitter:card'=>'summary_large_image'];if($page['canonical']!==null)$tags['og:url']=$page['canonical'];if($page['image']!=='')$tags['og:image']=$page['image'];
 foreach(['googleVerification'=>'google-site-verification','bingVerification'=>'msvalidate.01','yandexVerification'=>'yandex-verification'] as $field=>$name)if(!empty($page['verification'][$field]))$tags[$name]=$page['verification'][$field];
 $head='<title>'.nodenoSeoEscape($page['title']).'</title>'."\n";foreach($tags as $key=>$value)$head.='<meta '.(str_starts_with($key,'og:')?'property':'name').'="'.$key.'" content="'.nodenoSeoEscape($value).'">'."\n";
 if($page['canonical']!==null)$head.='<link rel="canonical" href="'.nodenoSeoEscape($page['canonical']).'">'."\n";foreach($page['alternates'] as $row)$head.='<link rel="alternate" hreflang="'.$row['locale'].'" href="'.nodenoSeoEscape($row['url']).'">'."\n";
 if($page['jsonld'])$head.='<script type="application/ld+json" data-nodeno-seo>'.json_encode($page['jsonld'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG).'</script>'."\n";
 $result=str_replace('</head>',$head.'</head>',$result);$result=preg_replace('~<html\b[^>]*>~i','<html lang="'.$page['locale'].'" dir="'.(nodenoLocaleRtl($page['locale'])?'rtl':'ltr').'">',$result);
 return preg_replace_callback('~<main\b([^>]*)>[\s\S]*?</main>~i',static fn(array $match):string=>'<main'.preg_replace('~\sdata-ssr-ready=["\x27][^"\x27]*["\x27]~i','',$match[1]).' data-ssr-ready="true">'.$page['body'].'</main>',$result);
}
