 $rows=[];if($kind==='products'){foreach(nodenoSeoProducts($catalog) as $p)$rows[]=['url'=>nodenoSeoUrl('product',$locale,['product'=>$p['id']]),'images'=>nodenoSeoImages($p,$catalog)];}else{foreach(['home','catalog','categories','help','shipping','wholesale','sets'] as $type)$rows[]=['url'=>nodenoSeoUrl($type,$locale)];foreach($catalog['furnitureSets']??[] as $set)$rows[]=['url'=>nodenoSeoUrl('sets',$locale,['set'=>$set['id']])];foreach($catalog['categories']??[] as $c)if(nodenoSeoProducts($catalog,$c['id']))$rows[]=['url'=>nodenoSeoUrl('catalog',$locale,['category'=>$c['id']])];
  $pages=(int)ceil(count(nodenoSeoDistinct(nodenoSeoProducts($catalog)))/24);for($pg=2;$pg<=$pages;$pg++)$rows[]=['url'=>nodenoSeoUrl('catalog',$locale,['pg'=>$pg])];
  foreach($catalog['categories']??[]as $category){$pages=(int)ceil(count(nodenoSeoDistinct(nodenoSeoProducts($catalog,$category['id'])))/24);for($pg=2;$pg<=$pages;$pg++)$rows[]=['url'=>nodenoSeoUrl('catalog',$locale,['category'=>$category['id'],'pg'=>$pg])];}
